<script setup>
import {ref,onMounted,watch} from 'vue'
import {request as directRequest} from './client'
function request(module,method,args={},verb='POST'){if(!props.general)return directRequest(module,method,args,verb);if(module==='learning_spaces')return directRequest('public_student','classes',args,'GET');return directRequest('public_student','action',{module,method,args})}
import Icon from '../Icon.vue'
import Programmes from './Programmes.vue'
import DemoLesson from './DemoLesson.vue'
const approved=ref(false),copied=ref(false),notice=ref('')
async function openEnrollment(r){keyRoom.value=r;enrollmentKey.value='';notice.value='';error.value='';approved.value=false;try{approved.value=(await request('class_keys','key_status',{classroom:r.name},'GET')).payment_approved}catch(e){error.value=e.message}}
async function resendKey(){busy.value=true;error.value='';try{await request('class_keys','resend',{classroom:keyRoom.value.name});notice.value='New key requested. Check your notifications or email. It expires in 15 minutes; your previous key no longer works.';window.dispatchEvent(new Event('sisu-notifications'))}catch(e){error.value=e.message}finally{busy.value=false}}
const demoClass=ref(null),keyRoom=ref(null),enrollmentKey=ref(''),paymentRoom=ref(null),bank=ref(null)
async function openDemo(r){if(!r.unlocked||r.requires_registration){demoClass.value=r;return}busy.value=true;error.value='';try{await directRequest('demo_learning','enter_classroom',{classroom:r.name});window.location.assign('/campus?classroom='+encodeURIComponent(r.name)+'#classrooms')}catch(e){error.value=e.message}finally{busy.value=false}}
async function redeem(){busy.value=true;error.value='';try{await request('class_keys','redeem',{classroom:keyRoom.value.name,key:enrollmentKey.value});keyRoom.value=null;enrollmentKey.value='';await load();emit('refresh')}catch(e){error.value=e.message}finally{busy.value=false}}
async function payment(r){error.value='';try{bank.value=await request('class_keys','bank_details',{classroom:r.name},'GET');paymentRoom.value=r;copied.value=false}catch(e){error.value=e.message}}
async function copyBank(){try{await navigator.clipboard.writeText(bank.value.instructions);copied.value=true}catch{error.value='Select the bank details and copy them manually.'}}
const props=defineProps({general:Boolean,profile:{type:String,default:''}}),emit=defineEmits(['room','navigate','refresh','payment'])
const rows=ref([]),page=ref(0),more=ref(false),busy=ref(false),error=ref('')
let sequence=0
const labels={module_locked:'Complete the preceding module',available:'Available to enrol',unlocked:'Unlocked',pending:'Slip submitted · awaiting payment approval',key:'Payment approved · ready to enroll',payment:'Payment required'}
async function load(){const run=++sequence;busy.value=true;error.value='';try{const data=await request('learning_spaces','classes',{profile:props.profile,page:page.value});if(run===sequence){rows.value=data.classes;more.value=data.has_more}}catch(e){if(run===sequence)error.value=e.message}finally{if(run===sequence)busy.value=false}}
async function join(r){busy.value=true;error.value='';try{await request(r.programme?'teaching':'catalog',r.programme?'enroll_programme':'join_class',r.programme?{programme:r.programme}:{classroom:r.name});if(r.programme){const details=await request('programme_courses','payment_details',{programme:r.programme},'GET');if(details.invoice)sessionStorage.setItem('sisu-payment-invoice',details.invoice)}await load();emit('refresh');if(r.fee_mode!=='Free'||r.programme)emit('payment',r);else emit('room',r)}catch(e){error.value=e.message}finally{busy.value=false}}

watch(()=>props.profile,()=>{page.value=0;load()});onMounted(load)
</script>
<template><DemoLesson v-if="demoClass" :classroom="demoClass" @close="demoClass=null" @unlocked="load"/><section class="student-classrooms"><header class="page-heading"><div><span class="eyebrow">YOUR NEXT CHAPTER</span><h1>My classrooms</h1><p>{{profile?'Classes and programme modules from your selected provider.':'Your enrolled classes. Choose a followed provider above to discover more.'}}</p></div><button class="button subtle" :disabled="busy" @click="load">Refresh</button></header><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="busy" role="status">Loading…</p><Programmes general :profile="profile" :rooms="rows" @room="emit('room',$event)" @navigate="emit('navigate',$event)" @refresh="load"/><div class="learning-class-grid"><article v-for="r in rows" :key="r.name" class="panel"><div class="class-cover" :class="{photo:!!r.cover_image}"><img v-if="r.cover_image" :src="r.cover_image" alt=""/><div v-else class="class-cover-art" aria-hidden="true"><Icon name="BookOpen" :size="58"/><span class="cover-orbit"></span></div><span class="cover-label">{{r.programme?'Programme module':r.fee_mode==='Free'?'Free learning':'Live & learning'}}</span></div><div class="class-copy"><small>{{r.programme?'Programme module':r.subject||'Classroom'}}</small><h2>{{r.title}}</h2><div class="class-teacher"><span class="teacher-monogram">{{r.teacher_name?.[0]||'T'}}</span><div><strong>{{r.teacher_name}}</strong><small v-if="r.teacher_id">{{r.teacher_id}}</small></div></div><span class="class-status" :class="r.state"><Icon :name="r.state==='unlocked'?'CheckCircle2':r.state==='pending'?'Clock':'BookOpen'" :size="15"/>{{r.demo?(r.unlocked?'Demo unlocked':'Demo locked'):r.state==='unlocked'&&r.payment_approved?'Payment approved · unlocked':labels[r.state]}}</span><p v-if="!r.demo&&r.state==='available'">{{r.programme?'One programme payment includes all its modules.':r.fee_mode==='Free'?'Free class':'Class fee: LKR '+r.fee}}</p><div v-if="keyRoom?.name===r.name" class="inline-enrollment"><form @submit.prevent="redeem"><label :for="'key-'+r.name">Enrollment key</label><input :id="'key-'+r.name" v-model="enrollmentKey" placeholder="Enter your enrollment key" required maxlength="64" autocomplete="off"><button class="button primary" :disabled="busy||!enrollmentKey.trim()">Enroll</button></form><p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert" class="error">{{error}}</p><button v-if="approved" class="text-button" :disabled="busy" @click="resendKey">Resend enrollment key</button><button v-else class="text-button" :disabled="busy" @click="join(r)">Pay and upload your slip to get an enrollment key</button><small v-if="approved">Your personal key expires after 15 minutes.</small><button class="text-button" @click="keyRoom=null">Cancel</button></div><button v-else-if="r.demo" class="button primary" :disabled="busy" @click="openDemo(r)">{{r.unlocked?'View classroom':'Enter enrollment key'}}</button><button v-else-if="r.requires_registration" class="button primary" @click="emit('navigate','connections')">Register with provider</button><button v-else-if="r.state==='key'" class="button primary" @click="openEnrollment(r)">Enroll now</button><button v-else-if="r.state==='available'" class="button primary" :disabled="busy" @click="r.fee_mode==='Free'?join(r):openEnrollment(r)">{{r.programme?'Enrol in programme':r.fee_mode==='Free'?'View classroom':'Enroll now'}}</button><button v-else-if="r.state==='unlocked'" class="button primary" @click="emit('room',r)">View classroom</button><button v-else-if="r.state==='payment'" class="button primary" @click="openEnrollment(r)">Enroll now</button><button v-else class="button subtle" @click="emit('payment',r)">{{r.state==='pending'?'View payment review':'Upload payment slip'}}</button></div></article></div><p v-if="!busy&&!error&&!rows.length">No classes here yet. Follow a provider in Teachers & institutes and select it above.</p><div class="inline"><button class="button subtle" :disabled="busy||!page" @click="page--;load()">Previous</button><button class="button subtle" :disabled="busy||!more" @click="page++;load()">Next</button></div></section></template>
<style scoped>.learning-class-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:24px;margin:24px 0}.learning-class-grid article{overflow:hidden}.learning-class-grid img{width:100%;height:150px;object-fit:cover}.class-copy{padding:24px;display:grid;gap:16px}.class-copy h2{font-size:21px}.class-copy p{line-height:1.6}.activation-form{padding:24px;margin-top:24px;display:grid;gap:16px}.activation-form input{display:block;padding:14px;border:1px solid var(--student-border);border-radius:10px;margin-top:8px;width:100%}</style>

<style scoped>
.learning-class-grid{grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:26px}
.learning-class-grid article.panel{padding:0;border-radius:22px;border:1px solid #ece5f6;background:var(--student-card,#fff);box-shadow:0 8px 26px rgba(38,21,68,.06);transition:box-shadow .22s ease,transform .22s ease,border-color .22s ease;display:flex;flex-direction:column}
.learning-class-grid article:hover{box-shadow:0 16px 36px rgba(86,40,141,.13);border-color:#d8c8f0;transform:translateY(-3px)}
.class-cover{height:172px;position:relative;overflow:hidden;background:linear-gradient(135deg,#171236 0%,#261d54 58%,#362773 100%)}
.class-cover img{height:100%;width:100%;object-fit:cover}
.class-cover-art{height:100%;display:grid;place-items:center;color:#c4b5fd}
.class-cover-art>svg{transform:rotate(-8deg);z-index:1;filter:drop-shadow(0 8px 18px rgba(15,10,35,.35))}
.cover-orbit{position:absolute;width:148px;height:148px;border:1.5px solid rgba(167,139,250,.28);border-radius:50%;right:18px;top:-28px}
.cover-orbit:after{content:'';position:absolute;width:210px;height:210px;left:-175px;top:82px;border-radius:50%;background:radial-gradient(circle,rgba(167,139,250,.22),transparent 70%)}
.cover-label{position:absolute;left:16px;top:16px;padding:6px 11px;border-radius:999px;background:rgba(255,255,255,.14);backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,.22);color:#f6f3ff;font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}
.class-copy{flex:1;padding:23px;gap:14px}
.class-copy>small{text-transform:uppercase;letter-spacing:.1em;font-size:10.5px;font-weight:750;color:#6c3cb5}
.class-copy h2{line-height:1.32;margin:0;font-size:19.5px;font-weight:800;letter-spacing:-.015em;color:var(--student-ink,#1d172b)}
.class-teacher{display:flex;align-items:center;gap:11px}
.teacher-monogram{height:38px;width:38px;border-radius:50%;background:linear-gradient(135deg,#f3effa,#e3d6f8);border:2px solid #fff;box-shadow:0 4px 10px rgba(86,40,141,.12);color:#56288d;font-weight:800;display:grid;place-items:center}
.class-teacher strong{font-size:13px;font-weight:700;color:var(--student-ink,#1d172b)}
.class-teacher small{display:block;font-size:10.5px;color:#7b728c;margin-top:3px}
.class-status{display:inline-flex;align-items:center;gap:7px;font-size:11.5px;font-weight:700;padding:8px 12px;border-radius:999px;background:#f4effc;color:#56288d;width:fit-content}
.class-status.unlocked{background:#e9f7ef;color:#1f6e45}
.class-status.pending{background:#fff5df;color:#795b18}
.class-copy>.button{width:100%;margin-top:auto;min-height:44px;justify-content:center;border-radius:999px;font-weight:750;box-shadow:0 8px 18px rgba(86,40,141,.18)}
.class-copy>p{font-size:12.5px;color:#5e566e;margin:0}
@media(max-width:500px){.learning-class-grid{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){.learning-class-grid article:hover{transform:none}}
</style>

<style scoped>.inline-enrollment{display:grid;gap:12px}.inline-enrollment form{display:grid;gap:10px}.inline-enrollment input{width:100%;box-sizing:border-box;padding:12px;border:1px solid var(--student-border,#ddd);border-radius:10px;font:inherit}.inline-enrollment input::placeholder{color:#8b8498;font-size:13px}.inline-enrollment .text-button{text-align:left;white-space:normal;line-height:1.5}</style>
